		require.NoError(t, err)
		require.NotEqual(t, cacheMiss, rsp.Header.Get("X-Cache"))
		require.NotEqual(t, cacheHit, rsp.Header.Get("X-Cache"))
	})

	t.Run("request with no-store directive", func(t *testing.T) {
